begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email) select ('ab200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','copy-'||n||'@example.invalid' from generate_series(1,4)n;
insert into public.staff_users(user_id,role) values('ab200000-0000-4000-8000-000000000001','office'),('ab200000-0000-4000-8000-000000000002','admin'),('ab200000-0000-4000-8000-000000000003','technician');
insert into public.catalog_items(id,code,name,category,unit,cost_cents,sale_cents,vat_basis_points,created_by,created_payload) values('cd200001-0000-4000-8000-000000000001','COPY-TEST','Praca','service','hour',100,200,2300,'ab200000-0000-4000-8000-000000000001','{}');
create function pg_temp.fields() returns jsonb language sql as $$select jsonb_build_object('name','Zestaw źródłowy','description','Opis źródła','workType','split','archived',false,'lines',(select jsonb_agg(jsonb_build_object('id','df200001-0000-4000-8000-'||lpad(n::text,12,'0'),'catalogId','cd200001-0000-4000-8000-000000000001','quantityMills',n*1250)||case when n=1 then '{}'::jsonb else jsonb_build_object('quantitySource',(array['fixed','length','area','labor','travel'])[n]) end order by n) from generate_series(1,5)n))$$;
create function pg_temp.input(n integer default 1,version integer default 0) returns jsonb language sql as $$select jsonb_build_object('id','ee200001-0000-4000-8000-'||lpad(n::text,12,'0'),'sourceVersion',version,'name','Komfort')$$;
create function pg_temp.copy(input jsonb default pg_temp.input()) returns jsonb language sql as $$select public.duplicate_installation_template('dd200001-0000-4000-8000-000000000001',input)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab200000-0000-4000-8000-000000000001',true);
select public.save_installation_template('dd200001-0000-4000-8000-000000000001',null,pg_temp.fields());
select throws_ok($$select pg_temp.copy(pg_temp.input(1,1))$$,'40001',null,'Stale source rejected');
select throws_ok($$select pg_temp.copy(pg_temp.input()||'{"fields":{}}')$$,'22023',null,'Client cannot forge source fields');
select throws_ok($$select pg_temp.copy(jsonb_set(pg_temp.input(),'{name}','""'))$$,'22023',null,'Empty name rejected');
select throws_ok($$select pg_temp.copy(jsonb_set(pg_temp.input(),'{id}','"dd200001-0000-4000-8000-000000000001"'))$$,'22023',null,'Cannot overwrite source');
select throws_ok($$select public.duplicate_installation_template('dd200001-0000-4000-8000-000000000099',pg_temp.input())$$,'42501',null,'Missing source rejected');
select is(pg_temp.copy()->'fields'->>'name','Komfort','Copy has chosen name');
select is(pg_temp.copy()->'fields'->>'description','Opis źródła','Description retained');
select is(pg_temp.copy()->'fields'->>'workType','split','Work type retained');
select is(jsonb_array_length(pg_temp.copy()->'fields'->'lines'),5,'Every row copied including repeated product');
select ok(not(pg_temp.copy()->'fields'->'lines'->0?'quantitySource'),'Legacy fixed rule retained');
select is(pg_temp.copy()->'fields'->'lines'->1->>'quantitySource','length','Length rule retained');
select is(pg_temp.copy()->'fields'->'lines'->2->>'quantitySource','area','Area rule retained');
select is(pg_temp.copy()->'fields'->'lines'->3->>'quantitySource','labor','Labor rule retained');
select is(pg_temp.copy()->'fields'->'lines'->4->>'quantitySource','travel','Travel rule retained');
select is(pg_temp.copy()->'fields'->'lines'->2->>'quantityMills','3750','Coefficient retained');
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.copy()->'fields'->'lines') a join jsonb_array_elements(pg_temp.fields()->'lines') b on a->>'id'=b->>'id'),'No shared row identities');
select is((select count(distinct l->>'id')::int from jsonb_array_elements(pg_temp.copy()->'fields'->'lines')l),5,'New row identities unique');
select is(public.installation_template_detail('dd200001-0000-4000-8000-000000000001')->'template'->>'version','0','Source unchanged');
select throws_ok($$select pg_temp.copy(jsonb_set(pg_temp.input(),'{name}','"Changed"'))$$,'40001',null,'Different retry rejected');
select public.save_installation_template('ee200001-0000-4000-8000-000000000001',0,jsonb_set(pg_temp.copy()->'fields','{description}','"Tylko kopia"'));
select is(pg_temp.copy()->'fields'->>'description','Tylko kopia','Exact retry returns original identity after editing copy');
select is(public.installation_template_detail('dd200001-0000-4000-8000-000000000001')->'template'->'fields'->>'description','Opis źródła','Editing copy does not edit source');
select public.save_installation_template('dd200001-0000-4000-8000-000000000001',0,pg_temp.fields()||'{"archived":true}');
select is(pg_temp.copy()->>'id','ee200001-0000-4000-8000-000000000001','Exact retry works after source changes');
select is(pg_temp.copy(pg_temp.input(2,1))->'fields'->>'archived','false','Archived source creates active copy');
select throws_ok($$select pg_temp.copy(jsonb_set(pg_temp.input(2,1),'{id}','"dd200001-0000-4000-8000-000000000001"'))$$,'22023',null,'Existing source id protected');
reset role;
select is((select count(*)::int from public.audit_logs where table_name='installation_templates' and row_id='dd200001-0000-4000-8000-000000000001'),2,'Only intentional source creation and archive audited');
select is((select count(*)::int from public.installation_template_copies where source_id='dd200001-0000-4000-8000-000000000001'),2,'Retries do not add ledger entries');
update public.catalog_items set archived=true where id='cd200001-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.copy(pg_temp.input(3,1))$$,'22023',null,'Inactive product blocks whole copy');
reset role;
select is((select count(*)::int from public.installation_templates where id='ee200001-0000-4000-8000-000000000003'),0,'Rejected copy leaves no partial data');
set local role authenticated;
select set_config('request.jwt.claim.sub','ab200000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.copy()$$,'40001',null,'Other actor cannot replay request');
reset role;
update public.catalog_items set archived=false where id='cd200001-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.copy(pg_temp.input(4,1))->>'version','0','Admin can duplicate');
select set_config('request.jwt.claim.sub','ab200000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.copy(pg_temp.input(5,1))$$,'42501',null,'Technician denied');
select set_config('request.jwt.claim.sub','ab200000-0000-4000-8000-000000000004',true);
select throws_ok($$select pg_temp.copy(pg_temp.input(5,1))$$,'42501',null,'No staff role denied');
reset role;
insert into public.account_access(user_id,blocked) values('ab200000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','ab200000-0000-4000-8000-000000000001',true);
select throws_ok($$select pg_temp.copy()$$,'42501',null,'Blocked actor denied even retry');
select throws_ok($$select * from public.installation_template_copies$$,'42501',null,'Ledger private');
reset role;
set local role anon;
select throws_ok($$select pg_temp.copy()$$,'42501',null,'Anonymous denied');
select * from finish();
rollback;
